def open_responses(path):
    if path == "-":
        raise ValueError("standard input is not an input file")
    try:
        info = os.stat(path)
        if not stat.S_ISREG(info.st_mode):
            raise ValueError("input is not a regular file")
        if info.st_size > RESPONSES_LIMIT:
            raise ValueError("response file is too large")
        stream = open(path, "rb")
    except (OSError, ValueError) as error:
        if isinstance(error, ValueError):
            raise
        raise ValueError("cannot read response file") from error
    if not stat.S_ISREG(os.fstat(stream.fileno()).st_mode):
        stream.close()
        raise ValueError("input is not a regular file")
    return stream


